<template><div class="page-container redaction-page"><PageHeader title="Hàng đợi che dữ liệu" description="Phê duyệt, thực thi và xác minh yêu cầu che thông tin nhạy cảm theo chuỗi kiểm soát." :breadcrumbs="[{label:'Bằng chứng'},{label:'Redaction'}]"><template #actions><BaseButton variant="secondary" :loading="loading" @click="loadRedactions">Làm mới</BaseButton></template></PageHeader>
<section class="queue-panel"><header><div><h2>Yêu cầu redaction</h2><p>{{ requests.length }} yêu cầu trong trạng thái đã chọn</p></div><BaseSelect id="redaction-status" v-model="statusFilter" aria-label="Lọc trạng thái" @update:model-value="commitFilter"><option value="">Tất cả trạng thái</option><option value="PendingApproval">Chờ phê duyệt</option><option value="Approved">Đã phê duyệt</option><option value="Performed">Đã thực thi</option><option value="Verified">Đã xác minh</option></BaseSelect></header>
<DataTable :columns="columns" :rows="requests" row-key="redactionRequestId" :loading="loading" :error="loadError" :permission-denied="permissionDenied" empty-title="Không có yêu cầu redaction" empty-description="Không có yêu cầu nào trong trạng thái đã chọn."><template #retry><BaseButton variant="secondary" @click="loadRedactions">Thử lại</BaseButton></template><template #cell-redactionRequestId="{value}">#{{ value }}</template><template #cell-evidenceItemId="{value}">#{{ value }}</template><template #cell-privacyLabel="{value}"><StatusBadge :status="value==='Biometric'?'critical':'warning'" :label="privacyLabel(value)"/></template><template #cell-reason="{value}"><span class="reason">{{ value||'Không có lý do' }}</span></template><template #cell-status="{value}"><StatusBadge :status="statusSemantic(value)" :label="statusLabel(value)" dot/></template><template #actions="{row}"><BaseButton v-if="row.status==='PendingApproval'" variant="ghost" size="small" @click="requestAction('approve',row)">Phê duyệt</BaseButton><BaseButton v-else-if="row.status==='Approved'" variant="ghost" size="small" @click="openPerform(row)">Thực thi</BaseButton><BaseButton v-else-if="row.status==='Performed'" variant="ghost" size="small" @click="requestAction('verify',row)">Xác minh</BaseButton></template></DataTable></section>
<BaseModal :open="Boolean(performTarget)" :title="`Thực thi redaction #${performTarget?.redactionRequestId||''}`" description="Nhập tham chiếu lưu trữ của bản đã che dữ liệu." @close="performTarget=null"><form id="redaction-perform-form" class="perform-form" @submit.prevent="perform"><BaseField for-id="redacted-reference" label="Tham chiếu lưu trữ" required description="Đường dẫn hoặc object key đã được hệ thống cấp." :error="performSubmitted&&!storageReference.trim()?'Tham chiếu lưu trữ là bắt buộc.':''" v-slot="field"><BaseInput id="redacted-reference" v-model="storageReference" :describedby="field.describedby" :invalid="field.invalid" placeholder="evidence/redacted/2026/..."/></BaseField><p v-if="actionError" class="form-error" role="alert">{{ actionError }}</p></form><template #footer><BaseButton variant="secondary" :disabled="busy" @click="performTarget=null">Hủy</BaseButton><BaseButton type="submit" form="redaction-perform-form" :loading="busy">Xác nhận thực thi</BaseButton></template></BaseModal>
<ConfirmDialog :open="Boolean(actionTarget)" :title="actionKind==='approve'?'Phê duyệt yêu cầu redaction?':'Xác minh redaction hoàn tất?'" :description="actionKind==='approve'?'Yêu cầu sẽ chuyển sang trạng thái sẵn sàng thực thi.':'Bản đã che dữ liệu sẽ được đánh dấu đã xác minh trong audit trail.'" :confirm-label="actionKind==='approve'?'Phê duyệt':'Xác minh'" :loading="busy" @cancel="actionTarget=null" @confirm="confirmAction"/></div></template>
<script setup>import{onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{enterpriseApi}from'../services/enterpriseSecurityApi';import BaseButton from'../components/ui/BaseButton.vue';import BaseField from'../components/ui/BaseField.vue';import BaseInput from'../components/ui/BaseInput.vue';import BaseModal from'../components/ui/BaseModal.vue';import BaseSelect from'../components/ui/BaseSelect.vue';import ConfirmDialog from'../components/ui/ConfirmDialog.vue';import DataTable from'../components/ui/DataTable.vue';import PageHeader from'../components/ui/PageHeader.vue';import StatusBadge from'../components/ui/StatusBadge.vue';import{useToasts}from'../composables/useToasts';
const route=useRoute(),router=useRouter(),{success,error:showError}=useToasts();const requests=ref([]),loading=ref(true),loadError=ref(''),permissionDenied=ref(false),statusFilter=ref(''),busy=ref(false),actionTarget=ref(null),actionKind=ref(''),performTarget=ref(null),storageReference=ref(''),performSubmitted=ref(false),actionError=ref('');const columns=[{key:'redactionRequestId',label:'Yêu cầu'},{key:'evidenceItemId',label:'Evidence'},{key:'privacyLabel',label:'Nhãn riêng tư'},{key:'reason',label:'Lý do'},{key:'status',label:'Trạng thái'}];function applyQuery(){statusFilter.value=String(route.query.status||'')}function commitFilter(){router.replace({query:{status:statusFilter.value||undefined}})}async function loadRedactions(){loading.value=true;loadError.value='';permissionDenied.value=false;try{const data=(await enterpriseApi.getRedactionRequests({status:statusFilter.value||undefined})).data;requests.value=Array.isArray(data)?data:[]}catch(error){requests.value=[];if(error.response?.status===403)permissionDenied.value=true;else loadError.value=error.response?.data?.message||'Không thể tải hàng đợi redaction.'}finally{loading.value=false}}function requestAction(kind,row){actionKind.value=kind;actionTarget.value=row}async function confirmAction(){if(!actionTarget.value)return;busy.value=true;const id=actionTarget.value.redactionRequestId;try{if(actionKind.value==='approve')await enterpriseApi.approveRedaction(id,{});else await enterpriseApi.verifyRedaction(id,{});success(actionKind.value==='approve'?'Đã phê duyệt redaction':'Đã xác minh redaction');actionTarget.value=null;await loadRedactions()}catch(error){showError('Không thể cập nhật redaction',error.response?.data?.message||'Yêu cầu chưa được thay đổi.')}finally{busy.value=false}}function openPerform(row){performTarget.value=row;storageReference.value='';performSubmitted.value=false;actionError.value=''}async function perform(){performSubmitted.value=true;if(!storageReference.value.trim()||!performTarget.value)return;busy.value=true;actionError.value='';try{await enterpriseApi.performRedaction(performTarget.value.redactionRequestId,{redactedStorageReference:storageReference.value.trim()});performTarget.value=null;success('Đã ghi nhận bản redaction');await loadRedactions()}catch(error){actionError.value=error.response?.data?.message||'Không thể thực thi redaction. Tham chiếu nhập vẫn được giữ lại.'}finally{busy.value=false}}function statusSemantic(value){return{Verified:'success',Performed:'info',Approved:'info',PendingApproval:'warning'}[value]||'neutral'}function statusLabel(value){return{Verified:'Đã xác minh',Performed:'Đã thực thi',Approved:'Đã phê duyệt',PendingApproval:'Chờ phê duyệt'}[value]||value}function privacyLabel(value){return value==='Biometric'?'Sinh trắc học':value||'Không phân loại'}onMounted(()=>{applyQuery();loadRedactions()});watch(()=>route.query,()=>{applyQuery();loadRedactions()},{deep:true})</script>
<style scoped>.redaction-page{display:grid;gap:var(--space-6)}.queue-panel{display:grid;gap:var(--space-4)}.queue-panel>header{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--space-4)}.queue-panel h2{font-size:var(--type-h2-size)}.queue-panel header p{color:var(--text-muted);font-size:var(--type-body-size)}.queue-panel :deep(.vs-select){width:min(100%,240px)}.reason{display:block;max-width:46ch;overflow:hidden;text-overflow:ellipsis}.perform-form{display:grid;gap:var(--space-4)}.form-error{padding:var(--space-3);border:1px solid var(--status-danger-border);border-radius:var(--radius-control);background:var(--status-danger-bg);color:var(--status-danger-text)}@media(max-width:640px){.queue-panel>header{align-items:stretch;display:grid}.queue-panel :deep(.vs-select){width:100%}}</style>
